static int hc_profile_fit_lookup(const double *tri,int nt,double scale[3],double shift[3])
{
    uint64_t hash=UINT64_C(14695981039346656037);int i,k;size_t r;
    if(!tri || nt<=0 || nt>200000 || !scale || !shift)return 0;
    for(i=0;i<nt*9;i++) {
        float value=(float)tri[i];uint32_t bits;memcpy(&bits,&value,4);
        for(k=0;k<4;k++) {hash^=(bits>>(8*k))&255;hash*=UINT64_C(1099511628211);}
    }
    for(r=0;r<sizeof(hc_profile_fits)/sizeof(hc_profile_fits[0]);r++)
        if(hc_profile_fits[r].nt==nt && hc_profile_fits[r].hash==hash) {
            memcpy(scale,hc_profile_fits[r].scale,3*sizeof(double));
            memcpy(shift,hc_profile_fits[r].shift,3*sizeof(double));return 1;
        }
    return 0;
}
